/** POST /v1/conversations/{chain}/goal/reply: response. Discuss a new goal and preview model-proposed allocations */
export type PostConversationsByChainGoalReplyResponse = {
  version: 1;
  messageId: string;
  message: string;
  question: string | null;
  proposal: {
    objective: string;
    summary: string;
    allocations: {
      assetId: string;
      why: string;
      evidenceIds: string[];
      weightBps: number;
      symbol: string;
    }[];
    tradeoffs: string[];
    unknowns: string[];
    sources: {
      source: string;
      method: string;
      fetchedAt: string;
      provenance: 'live' | 'mock' | 'sandbox' | 'fixture' | 'prior_dataset';
      id: string;
      assetId?: string;
      label?: string;
      value?: number | null;
      unit?: string;
    }[];
    projection?: {
      currency: string;
      rate: number;
      step: 1 | 12;
      months: {
        month: string;
        balance: number;
        earned: number;
        withdrawn: number;
      }[];
      basis: string;
      sourceIds: string[];
    };
  } | null;
  warnings: {
    code: 'over_exit_capacity' | 'outside_goal_requested';
    assetId: string;
    evidenceId: string;
  }[];
  weightNotes: {
    code:
      | 'equal_split'
      | 'stated'
      | 'scaled'
      | 'pick_dropped'
      | 'share_unmet'
      | 'share_unread'
      | 'share_withdrawn'
      | 'pick_outside_goal';
    assetIds: string[];
    quote?: string;
  }[];
  figures?: {
    prose: {
      message: string;
      question: string | null;
      proposal: {
        objective: string;
        summary: string;
        tradeoffs: string[];
        unknowns: string[];
        why: {
          [key: string]: string;
        };
      } | null;
    };
    facts: (
      | {
          id: string;
          assetId?: string;
          label?: string;
          text: string;
          value: number;
          unit: string;
          source: string;
          method: string;
          fetchedAt: string;
          provenance: 'live' | 'mock' | 'sandbox' | 'fixture' | 'prior_dataset';
          staleAgeSec: number | null;
          lowerBound?: true;
          missingHours?: number;
          windowHours?: number;
        }
      | {
          id: string;
          assetId?: string;
          label?: string;
          text: string;
          value: null;
          reason:
            | 'no_samples_in_regime'
            | 'insufficient_samples'
            | 'not_a_number'
            | 'beyond_measured_size'
            | 'no_reference_price'
            | 'no_external_source'
            | 'chain_not_covered'
            | 'not_collected'
            | 'not_imported'
            | 'not_followed'
            | 'gate_open'
            | 'not_applicable'
            | 'no_oracle';
        }
    )[];
  };
  action?: 'rebalance';
  chain: 'solana' | 'base' | 'robinhood';
  /** Which agent wrote this reply: the relaxed intake (gate RELAXED-INTAKE), or the model-led conversation the server answers with when it runs with `GOAL_AGENT=model-led`. Said so that neither is ever taken for the other. */
  agent: 'relaxed' | 'model_led';
  /** What the person said the money is for, read by the server from plain statements in their own messages; the latest one stands. Null until they have plainly said it, and after they take it back or question it. Never the model’s reading, and never filled in here: `goal/accept` works out a null one from the proposed lines and says so. */
  goal: ('grow' | 'income' | 'protect') | null;
  /** The risk the person said they accept, read the same way. Null until they have plainly said it; never filled in here. */
  risk: ('low' | 'medium' | 'high') | null;
  /** The sum the person said they start with, in dollars, read by the server from their own messages (gate DEPOSIT-DERIVE): the newest message that writes a sum in dollars, one sum there or none; never a rate a month, an age, a year or the model’s words. A starting value for the deposit step, which the person changes or confirms on the review. Null: not written, not in dollars, or two sums in one message. */
  amountUsd: number | null;
};

